    async def record_calibration_decision(
        self,
        calibration_session_id: str,
        *,
        idempotency_key: str,
        interpretation: str,
        next_action: AgentDecisionNextAction,
        assessment: typing.Optional[AgentDecisionAssessment] = OMIT,
        next_detail: typing.Optional[str] = OMIT,
        evidence_run_ids: typing.Optional[typing.Sequence[str]] = OMIT,
        evidence_task_ids: typing.Optional[typing.Sequence[str]] = OMIT,
        evidence_decision_ids: typing.Optional[typing.Sequence[str]] = OMIT,
        supersedes_decision_id: typing.Optional[str] = OMIT,
        experiment: typing.Optional[CalibrationExperimentPlanModel] = OMIT,
        conclusion: typing.Optional[CalibrationConclusionModel] = OMIT,
        model: typing.Optional[AgentModelIdentity] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AsyncHttpResponse[CalibrationDecisionResponse]:
        """
        Append a decision, as an agent session decision is appended to its audit.

        Only the session's creator records, in any status. Every cited pipeline run and decision
        must belong to the session and every cited task result must be on its chip (409 otherwise);
        QDash freezes what its records say about them. ``experiment`` proposes a run, which is then
        started with this decision's ID; ``conclusion`` states a recommendation that must rest on
        the cited evidence of its candidate (422 otherwise). A decision changes no calibration and
        starts nothing. A retry with the same key and request returns the same record.

        Parameters
        ----------
        calibration_session_id : str

        idempotency_key : str

        interpretation : str
            Concise reasoning for the decision, citing the evidence

        next_action : AgentDecisionNextAction

        assessment : typing.Optional[AgentDecisionAssessment]
            How the recorder judged the evidence; omitted when not stated

        next_detail : typing.Optional[str]

        evidence_run_ids : typing.Optional[typing.Sequence[str]]
            Pipeline runs of this session

        evidence_task_ids : typing.Optional[typing.Sequence[str]]
            Task results on the session's chip

        evidence_decision_ids : typing.Optional[typing.Sequence[str]]
            Earlier decisions of this session

        supersedes_decision_id : typing.Optional[str]

        experiment : typing.Optional[CalibrationExperimentPlanModel]

        conclusion : typing.Optional[CalibrationConclusionModel]

        model : typing.Optional[AgentModelIdentity]
            The model the client host reports for this record; client reported, not verified

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AsyncHttpResponse[CalibrationDecisionResponse]
            Successful Response
        """
        _response = await self._client_wrapper.httpx_client.request(
            f"calibration-sessions/{quote_path_param(calibration_session_id)}/decisions",
            method="POST",
            json={
                "idempotency_key": idempotency_key,
                "assessment": assessment,
                "interpretation": interpretation,
                "next_action": next_action,
                "next_detail": next_detail,
                "evidence_run_ids": evidence_run_ids,
                "evidence_task_ids": evidence_task_ids,
                "evidence_decision_ids": evidence_decision_ids,
                "supersedes_decision_id": supersedes_decision_id,
                "experiment": convert_and_respect_annotation_metadata(
                    object_=experiment, annotation=typing.Optional[CalibrationExperimentPlanModel], direction="write"
                ),
                "conclusion": convert_and_respect_annotation_metadata(
                    object_=conclusion, annotation=typing.Optional[CalibrationConclusionModel], direction="write"
                ),
                "model": convert_and_respect_annotation_metadata(
                    object_=model, annotation=typing.Optional[AgentModelIdentity], direction="write"
                ),
            },
            headers={
                "content-type": "application/json",
            },
            request_options=request_options,
            omit=OMIT,
        )
        try:
            if 200 <= _response.status_code < 300:
                _data = typing.cast(
                    CalibrationDecisionResponse,
                    parse_obj_as(
                        type_=CalibrationDecisionResponse,  # type: ignore
                        object_=_response.json(),
                    ),
                )
                return AsyncHttpResponse(response=_response, data=_data)
            if _response.status_code == 422:
                raise UnprocessableEntityError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        typing.Any,
                        parse_obj_as(
                            type_=typing.Any,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            _response_json = _response.json()
        except JSONDecodeError:
            raise ApiError(status_code=_response.status_code, headers=dict(_response.headers), body=_response.text)
        except ValidationError as e:
            raise ParsingError(
                status_code=_response.status_code, headers=dict(_response.headers), body=_response.json(), cause=e
            )
        raise ApiError(status_code=_response.status_code, headers=dict(_response.headers), body=_response_json)

